import{_ as r,o,c as e,a6 as a}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"共同骨架 · 先看它们有多像","description":"对比之前，先把不变的部分讲清：现代开源大模型共享同一套 decoder-only 骨架（RoPE + RMSNorm + Pre-Norm + SwiGLU），它们相对 GPT-2 的升级早已“达成共识”。真正还在分歧的，只有六个维度——本章给出总览地图。","frontmatter":{"title":"共同骨架 · 先看它们有多像","description":"对比之前，先把不变的部分讲清：现代开源大模型共享同一套 decoder-only 骨架（RoPE + RMSNorm + Pre-Norm + SwiGLU），它们相对 GPT-2 的升级早已“达成共识”。真正还在分歧的，只有六个维度——本章给出总览地图。","source":"https://daiw.org/manual/llm-anatomy/common-skeleton"},"headers":[],"relativePath":"manual/llm/llm-anatomy/common-skeleton.md","filePath":"manual/llm/llm-anatomy/common-skeleton.md"}'),n={name:"manual/llm/llm-anatomy/common-skeleton.md"};function s(d,t,l,i,g,m){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="共同骨架-·-先看它们有多像" tabindex="-1">共同骨架 · 先看它们有多像 <a class="header-anchor" href="#共同骨架-·-先看它们有多像" aria-label="Permalink to &quot;共同骨架 · 先看它们有多像&quot;">​</a></h1><blockquote><p>对比之前，先把不变的部分讲清：现代开源大模型共享同一套 decoder-only 骨架（RoPE + RMSNorm + Pre-Norm + SwiGLU），它们相对 GPT-2 的升级早已“达成共识”。真正还在分歧的，只有六个维度——本章给出总览地图。</p></blockquote><p>要看清差异，得先看清<strong>共性</strong>。不然你会把“大家都这么做”的东西，误当成某家的独门绝技。</p><p>这一章不讲任何一家的“绝活”，只做一件事：<strong>把 Qwen、Llama、DeepSeek、GLM 们共享的那副骨架摆出来</strong>。看完你会有个踏实的底：它们八成的结构，你在 nanoGPT 里已经读过了。</p><h2 id="一句话-全是-decoder-only-的-续写机" tabindex="-1">一句话：全是 decoder-only 的“续写机” <a class="header-anchor" href="#一句话-全是-decoder-only-的-续写机" aria-label="Permalink to &quot;一句话：全是 decoder-only 的“续写机”&quot;">​</a></h2><p>不管参数是 7B 还是 671B，今天主流的开源大模型，<strong>架构范式高度统一</strong>：</p><ul><li><strong>decoder-only</strong>：没有编码器，就是一摞 Transformer Block 从头叠到尾（和 nanoGPT 的 <code>GPT</code> 一模一样）。</li><li><strong>自回归 + 因果掩码</strong>：预测下一个 token，只能看左边——就是你在<a href="https://daiw.org/manual/nanogpt/attention" target="_blank" rel="noreferrer">注意力那章</a>里啃过的那道下三角掩码。</li><li><strong>一个 Block = 注意力 + 前馈</strong>，两个子层各带一个归一化、各套一条残差。</li></ul><p>换句话说，<strong>nanoGPT 那张数据流图，拿去描述 DeepSeek-V3 的一个 Block，大体还是对的</strong>。区别不在“有没有这些零件”，而在“这些零件各自换成了什么型号”。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>2026 年的演进补记：连这副“共同骨架”也开始松动了</strong>。到了 2026 年的前沿旗舰，连“从头到尾一模一样的 decoder-only 堆叠”和“单车道残差流”这两条铁律都出现了突破：</p><ul><li><strong>编码-解码分工（CED）与条件记忆</strong>：<a href="https://daiw.org/manual/deepseek-v4-flash/ced" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a> 把 40 层主干拆成 <strong>20 层编码器 + 20 层解码器</strong>，预填充跑满 40 层、自回归生成只跑后 20 层解码器，还在第 2、14 层挂上了 99B 的 <strong>Engram</strong> 哈希查表记忆；</li><li><strong>跨层残差路由</strong>：<a href="https://daiw.org/manual/deepseek-v4-flash/mhc" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash 的 Single-Pass mHC</a> 把残差流扩成 4 条并行流，<a href="https://daiw.org/manual/kimi-k3/attn-res" target="_blank" rel="noreferrer">Kimi K3 的 AttnRes</a> 则让深层通过深度方向的 softmax 注意力直接回看浅层块表征。</li></ul></div><h2 id="相对-gpt-2-有四处-已经达成共识-的升级" tabindex="-1">相对 GPT-2，有四处“已经达成共识”的升级 <a class="header-anchor" href="#相对-gpt-2-有四处-已经达成共识-的升级" aria-label="Permalink to &quot;相对 GPT-2，有四处“已经达成共识”的升级&quot;">​</a></h2><p>nanoGPT 复刻的是 2019 年的 GPT-2。从那时到现在，有四个地方，<strong>几乎所有现代模型都做了同样的升级</strong>——这些是“已经有标准答案”的问题，不再是分歧点：</p><table tabindex="0"><thead><tr><th>零件</th><th>GPT-2 / nanoGPT 的老做法</th><th>现代标配</th><th>为什么换</th></tr></thead><tbody><tr><td><strong>位置编码</strong></td><td>学习式绝对位置嵌入（<code>wpe</code> 查表）</td><td><strong>RoPE</strong>（旋转位置编码）</td><td>相对位置、能外推到更长上下文</td></tr><tr><td><strong>归一化</strong></td><td>LayerNorm（减均值、除方差）</td><td><strong>RMSNorm</strong>（只除均方根）</td><td>少算一个均值，更快，效果不掉</td></tr><tr><td><strong>前馈激活</strong></td><td>GELU 的普通 MLP</td><td><strong>SwiGLU</strong>（门控 + SiLU）</td><td>同算力下效果更好，已成默认</td></tr><tr><td><strong>偏置项 bias</strong></td><td>Linear / LayerNorm 都带 bias</td><td>大多<strong>去掉 bias</strong></td><td>省参数、略快、还略稳（nanoGPT 也提到了）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>这张表值得记牢：<strong>当你读到某个新模型“用了 RoPE + RMSNorm + Pre-Norm + SwiGLU”，不必激动——那是 2024 年起的“出厂设置”，不是创新。</strong> 真正的创新，藏在下面那六个还没有标准答案的维度里。</p></div><p>顺带一提，Pre-Norm（把归一化放在子层<strong>前面</strong>）也基本成了默认——它比 GPT 原版的 Post-Norm 训练更稳。但注意，<strong>“归一化到底放哪儿”其实还没完全盖棺定论</strong>，这正是我们后面要单独对比的一维（OLMo 2 就偏要放回后面）。</p><h2 id="于是-真正的-战场-只剩六个维度" tabindex="-1">于是，真正的“战场”只剩六个维度 <a class="header-anchor" href="#于是-真正的-战场-只剩六个维度" aria-label="Permalink to &quot;于是，真正的“战场”只剩六个维度&quot;">​</a></h2><p>把上面这些共性摁住，各家大模型真正分道扬镳的地方，收拢起来其实<strong>就六个</strong>。这也是本专栏后面每一章的锚点：</p><table tabindex="0"><thead><tr><th>#</th><th>维度</th><th>核心问题</th><th>谁在这儿下了不同的注</th></tr></thead><tbody><tr><td>1</td><td><strong>注意力 / KV 缓存</strong></td><td>推理时怎么省下键值缓存的显存？</td><td>Llama/Qwen 用 GQA，DeepSeek 用 <strong>MLA / CSA2</strong>，Gemma/GPT-OSS 加<strong>滑动窗口</strong>，Qwen3.8/Kimi K3 上 <strong>3:1 线性混合注意力</strong></td></tr><tr><td>2</td><td><strong>前馈：稠密 vs MoE</strong></td><td>要不要把前馈拆成一堆“专家”稀疏激活？</td><td>DeepSeek/Llama4/GLM/Kimi 上 <strong>MoE</strong>，中小模型多留<strong>稠密</strong></td></tr><tr><td>3</td><td><strong>MoE 的配方</strong></td><td>专家多而小还是少而大？要不要共享专家？</td><td>DeepSeek“多而小 + 共享”，Llama4“少而大”，Qwen3“砍掉共享”（Qwen3.8 又加回），Kimi K3“潜空间 LatentMoE”</td></tr><tr><td>4</td><td><strong>归一化的位置</strong></td><td>Norm 放子层前、后，还是前后都放？</td><td>多数 <strong>Pre</strong>，OLMo 2 用 <strong>Post</strong>，Gemma 用<strong>三明治</strong>；QK-Norm 与注意力输出门控渐成标配</td></tr><tr><td>5</td><td><strong>长上下文</strong></td><td>RoPE 怎么外推到几十万乃至百万 token？</td><td>YaRN + Partial RoPE 为主，也有 <strong>NoPE</strong> 的激进实验</td></tr><tr><td>6</td><td><strong>训练侧与小执念</strong></td><td>训练目标、精度、宽深、bias…</td><td>DeepSeek 的 <strong>MTP / DSpark / FP8 / FP4</strong>；Kimi K2/K3 的 <strong>Muon + MXFP4</strong>；GPT-OSS 的<strong>宽</strong>与 <strong>attention sink</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>别被这张表吓到——它不是要你现在就记住每一格。它是一张<strong>地图</strong>：接下来每一章，我们会走进其中一格，把那一列的对比讲透。读完整个专栏再回看这张表，你会发现每一格都变成了你脑子里清晰的一段故事。</p></div><h2 id="一个提醒-这些维度不是孤立的" tabindex="-1">一个提醒：这些维度不是孤立的 <a class="header-anchor" href="#一个提醒-这些维度不是孤立的" aria-label="Permalink to &quot;一个提醒：这些维度不是孤立的&quot;">​</a></h2><p>六个维度里，<strong>前两条（注意力、MoE）是绝对的主角</strong>——它们直接决定“这个模型推理时要烧多少显存、多少算力”，也是各家技术报告里着墨最多的地方。后面几条更像“配平”的细节，重要，但不改变大局。</p><p>所以本专栏的顺序也照此安排：<strong>先啃两条主线（省 KV 缓存、稀疏化），再收拾其余维度，最后给每个模型画张脸谱、汇一张总表。</strong></p><p>骨架看清了，共识划走了，战场也圈定了。下一章，我们踏进第一个、也是最重要的战场——<strong>注意力</strong>。你会看到 MHA、MQA、GQA、MLA 这一串缩写，其实是同一个问题（“KV 缓存太占显存”）的一串越来越聪明的答案。👉 <a href="/Front2Full/manual/llm/llm-anatomy/attention-mha-gqa-mla">注意力：从 MHA 到 MQA、GQA、MLA</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Su et al. “RoFormer: Enhanced Transformer with Rotary Position Embedding.” 2021. arXiv:2104.09864. —— RoPE。</li><li>[2] Zhang &amp; Sennrich. “Root Mean Square Layer Normalization.” NeurIPS 2019. arXiv:1910.07467. —— RMSNorm。</li><li>[3] Shazeer. “GLU Variants Improve Transformer.” 2020. arXiv:2002.05202. —— SwiGLU。</li><li>[4] Xiong et al. “On Layer Normalization in the Transformer Architecture.” ICML 2020. arXiv:2002.04745. —— Pre-Norm 相对 Post-Norm 的训练稳定性。</li><li>[5] Radford et al. “Language Models are Unsupervised Multitask Learners.” 2019. —— GPT-2，本专栏的“老做法”基准。</li><li>[6] Raschka, S. “The Big LLM Architecture Comparison.” 2025. <a href="https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison" target="_blank" rel="noreferrer">https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison</a> —— 本专栏的对比框架与多处架构事实的主要参考。</li></ul>',24)])])}const p=r(n,[["render",s]]);export{h as __pageData,p as default};
